export function isValidPhoneNumber(phone: string): boolean {
  // E.164 format
  const phoneRegex = /^\+?[1-9]\d{1,14}$/;
  return phoneRegex.test(phone);
}

export function isNonEmptyString(value: unknown): value is string {
  return typeof value === 'string' && value.trim().length > 0;
}

export function isPositiveSafeInteger(value: unknown): value is number {
  return Number.isSafeInteger(value) && value > 0;
}

export function isValidISO3166CountryCode(code: string): boolean {
  // Simplified check - in reality would use a comprehensive list
  return /^[A-Z]{2}$/.test(code);
}

export function isValidISO4217CurrencyCode(code: string): boolean {
  // Simplified check - in reality would use a comprehensive list
  return /^[A-Z]{3}$/.test(code);
}

export function isValidUSStateCode(code: string): boolean {
  const validStates = [
    'AL', 'AK', 'AZ', 'AR', 'CA', 'CO', 'CT', 'DE', 'FL', 'GA', 'HI', 'ID', 'IL', 'IN', 'IA',
    'KS', 'KY', 'LA', 'ME', 'MD', 'MA', 'MI', 'MN', 'MS', 'MO', 'MT', 'NE', 'NV', 'NH', 'NJ',
    'NM', 'NY', 'NC', 'ND', 'OH', 'OK', 'OR', 'PA', 'RI', 'SC', 'SD', 'TN', 'TX', 'UT', 'VT',
    'VA', 'WA', 'WV', 'WI', 'WY'
  ];
  return validStates.includes(code);
}

export function isValidUSPostalCode(code: string): boolean {
  const postalCodeRegex = /^\d{5}(-\d{4})?$/;
  return postalCodeRegex.test(code);
}

